USE DATABASE MENDIX_APP;
USE SCHEMA AGENTS;

CREATE OR REPLACE FUNCTION MENDIX_APP.AGENTS.BL_DOC_ALERT("P_BL" VARCHAR, "P_CONTAINER" VARCHAR, "P_VESSEL" VARCHAR, "P_WEIGHT" FLOAT, "P_DATE" DATE)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT='Deterministic validation of an extracted BL. NULL means no anomalies.'
AS '
    NULLIF(
        RTRIM(
            IFF(P_BL IS NULL OR LENGTH(TRIM(P_BL)) = 0, ''BlNumber; '', '''')
            || IFF(P_CONTAINER IS NULL
                   OR LENGTH(TRIM(P_CONTAINER)) < 8
                   OR UPPER(P_CONTAINER) RLIKE ''.*[^A-Z0-9].*''
                   OR UPPER(P_CONTAINER) LIKE ''XXXX%'', ''ContainerNumber; '', '''')
            || IFF(P_VESSEL IS NULL OR LENGTH(TRIM(P_VESSEL)) <= 2, ''VesselName; '', '''')
            || IFF(P_WEIGHT IS NULL OR P_WEIGHT < 100 OR P_WEIGHT >= 100000, ''GrossWeightKg; '', '''')
            || IFF(P_DATE IS NULL OR P_DATE < ''2025-01-01''::DATE, ''DateOfIssue; '', '''')
            || IFF((MENDIX_APP.AGENTS.CARRIER_FROM_CODE(P_BL) IS NOT NULL
                    AND MENDIX_APP.AGENTS.CARRIER_FROM_CODE(P_CONTAINER) IS NOT NULL
                    AND MENDIX_APP.AGENTS.CARRIER_FROM_CODE(P_BL) <> MENDIX_APP.AGENTS.CARRIER_FROM_CODE(P_CONTAINER))
                   OR (MENDIX_APP.AGENTS.CARRIER_FROM_CODE(P_BL) IS NOT NULL
                    AND MENDIX_APP.AGENTS.CARRIER_FROM_VESSEL(P_VESSEL) IS NOT NULL
                    AND MENDIX_APP.AGENTS.CARRIER_FROM_CODE(P_BL) <> MENDIX_APP.AGENTS.CARRIER_FROM_VESSEL(P_VESSEL)),
                ''CarrierMismatch; '', ''''),
            ''; ''
        ), ''''
    )
';

CREATE OR REPLACE FUNCTION MENDIX_APP.AGENTS.BL_DOC_CONFIDENCE("P_BL" VARCHAR, "P_CONTAINER" VARCHAR, "P_VESSEL" VARCHAR, "P_WEIGHT" FLOAT, "P_DATE" DATE)
RETURNS FLOAT
LANGUAGE SQL
COMMENT='Extraction confidence 0-100 derived from BL_DOC_ALERT failure count.'
AS '
    ROUND(
        100.0 * (
            6 - COALESCE(
                    ARRAY_SIZE(SPLIT(
                        MENDIX_APP.AGENTS.BL_DOC_ALERT(P_BL, P_CONTAINER, P_VESSEL, P_WEIGHT, P_DATE),
                        ''; '')),
                    0)
        ) / 6.0, 0)::FLOAT
';

CREATE OR REPLACE FUNCTION MENDIX_APP.AGENTS.CALCULATE_DISTANCE("LAT1" FLOAT, "LON1" FLOAT, "LAT2" FLOAT, "LON2" FLOAT)
RETURNS FLOAT
LANGUAGE SQL
AS '
    6371 * 2 * ASIN(SQRT(
        POWER(SIN(RADIANS(LAT2 - LAT1) / 2), 2) +
        COS(RADIANS(LAT1)) * COS(RADIANS(LAT2)) *
        POWER(SIN(RADIANS(LON2 - LON1) / 2), 2)
    ))
';

CREATE OR REPLACE FUNCTION MENDIX_APP.AGENTS.CARRIER_FROM_CODE("P_CODE" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT='Carrier for a BL prefix or ISO 6346 container owner code; NULL when unknown.'
AS '
    CASE UPPER(LEFT(COALESCE(P_CODE, ''''), 4))
        WHEN ''MAEU'' THEN ''MAERSK''
        WHEN ''MSKU'' THEN ''MAERSK''
        WHEN ''MRKU'' THEN ''MAERSK''
        WHEN ''MSCU'' THEN ''MSC''
        WHEN ''MEDU'' THEN ''MSC''
        WHEN ''COSU'' THEN ''COSCO''
        WHEN ''CCLU'' THEN ''COSCO''
        WHEN ''CBHU'' THEN ''COSCO''
        WHEN ''HLCU'' THEN ''HAPAG_LLOYD''
        WHEN ''HLXU'' THEN ''HAPAG_LLOYD''
        WHEN ''ONEY'' THEN ''ONE''
        WHEN ''ONEU'' THEN ''ONE''
        WHEN ''EGLV'' THEN ''EVERGREEN''
        WHEN ''EISU'' THEN ''EVERGREEN''
        WHEN ''CMAU'' THEN ''CMA_CGM''
        WHEN ''OOLU'' THEN ''OOCL''
        WHEN ''APLU'' THEN ''APL''
        WHEN ''YMLU'' THEN ''YANG_MING''
        ELSE NULL
    END
';

CREATE OR REPLACE FUNCTION MENDIX_APP.AGENTS.CARRIER_FROM_VESSEL("P_VESSEL" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT='Carrier inferred from a vessel name keyword; NULL when not inferable.'
AS '
    CASE
        WHEN UPPER(COALESCE(P_VESSEL, '''')) LIKE ''%MAERSK%''    THEN ''MAERSK''
        WHEN UPPER(COALESCE(P_VESSEL, '''')) LIKE ''%COSCO%''     THEN ''COSCO''
        WHEN UPPER(COALESCE(P_VESSEL, '''')) LIKE ''%EVERGREEN%'' THEN ''EVERGREEN''
        WHEN UPPER(COALESCE(P_VESSEL, '''')) LIKE ''%HAPAG%''     THEN ''HAPAG_LLOYD''
        WHEN UPPER(COALESCE(P_VESSEL, '''')) LIKE ''%CMA %''      THEN ''CMA_CGM''
        WHEN UPPER(COALESCE(P_VESSEL, '''')) LIKE ''%OOCL%''      THEN ''OOCL''
        WHEN UPPER(COALESCE(P_VESSEL, '''')) LIKE ''%YANG MING%'' THEN ''YANG_MING''
        WHEN UPPER(COALESCE(P_VESSEL, '''')) RLIKE ''(^|.* )MSC( .*|$)'' THEN ''MSC''
        WHEN UPPER(COALESCE(P_VESSEL, '''')) RLIKE ''(^|.* )ONE( .*|$)'' THEN ''ONE''
        ELSE NULL
    END
';

CREATE OR REPLACE FUNCTION MENDIX_APP.AGENTS.GET_CONFIG("P_KEY" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
AS '(SELECT CONFIG_VALUE FROM APP_CONFIG WHERE CONFIG_KEY = P_KEY LIMIT 1)';

CREATE OR REPLACE FUNCTION MENDIX_APP.AGENTS.GET_PORT_NAME("PORT_CODE" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
AS '(SELECT PORT_NAME FROM PORT_MASTER WHERE PORT_CODE = $1 LIMIT 1)';

CREATE OR REPLACE FUNCTION MENDIX_APP.AGENTS.IS_RESTRICTED_HS_CODE("HS_CODE_VALUE" VARCHAR)
RETURNS BOOLEAN
LANGUAGE SQL
AS 'COALESCE((SELECT IS_RESTRICTED OR REQUIRES_PERMIT FROM HS_CODE_REFERENCE WHERE HS_CODE = $1 LIMIT 1), FALSE)';

CREATE OR REPLACE FUNCTION MENDIX_APP.AGENTS.PARSE_BL_NUMBER("BL_NUMBER" VARCHAR)
RETURNS OBJECT
LANGUAGE SQL
AS 'OBJECT_CONSTRUCT(''carrier_code'', SUBSTRING(BL_NUMBER, 1, 4), ''sequence'', SUBSTRING(BL_NUMBER, 5))';

CREATE OR REPLACE FUNCTION MENDIX_APP.AGENTS.VALIDATE_CONTAINER_NUMBER("CONTAINER_NUM" VARCHAR)
RETURNS BOOLEAN
LANGUAGE SQL
AS 'LENGTH(CONTAINER_NUM) = 11 AND REGEXP_LIKE(CONTAINER_NUM, ''^[A-Z]{4}[0-9]{7}$'')';
